61: function xpForNextLevel(level) { return 100 + (level - 1) * 25 }
62: function levelInfo(total = game.xp) {
63:   let level = 1, remaining = Math.max(0, Math.floor(total))
64:   while (remaining >= xpForNextLevel(level)) { remaining -= xpForNextLevel(level); level++ }
65:   return { level, current: remaining, needed: xpForNextLevel(level), percent: Math.min(100, remaining / xpForNextLevel(level) * 100) }
66: }
67: function awardXP(amount, reason, claimKey = null) {
68:   if (claimKey && game.xpClaims.includes(claimKey)) return false
69:   const reward = Math.max(0, Math.floor(Number(amount) || 0))
70:   if (!reward) return false
71:   if (claimKey) game.xpClaims.push(claimKey)
72:   game.xp += reward
73:   return true
74: }
