120:   const loci = GENES.map(g=>{const [a,b]=c.genome?.[g.key]||[0.5,0.5], expressed=Math.round((a+b)*50);return `<i class="chromosome-locus" style="--locus:${expressed}%" title="${esc(g.label)} ${expressed}%"></i>`}).join('')
121:   return `<div class="genome-summary"><div class="chromosome-art" aria-label="Chromosome map: ${GENES.length} paired loci">${loci}</div><div class="genome-summary-copy"><small>PAIRED CHROMOSOME · ${GENES.length} LOCI</small><code>${dnaSequence(c.genome).slice(0,22)}…</code></div><span>GEN ${c.generation||0}</span></div>${Object.entries(groups).map(([group,label])=>`<section class="gene-group"><div class="gene-group-title">${label}<span>${GENES.filter(g=>g.group===group).length} LOCI</span></div>${GENES.filter(g=>g.group===group).map(g=>{const [a,b]=c.genome?.[g.key]||[0.5,0.5], expressed=Math.round((a+b)*50);return `<div class="gene-visual" title="${esc(g.desc)}"><span class="gene-glyph" aria-hidden="true">${glyphs[g.key]||'◇'}</span><div class="gene-visual-main"><div class="gene-name-line"><b>${esc(g.label)}</b><span>${expressed}%</span></div><div class="allele-visual" role="img" aria-label="${esc(g.label)}: allele A ${Math.round(a*100)}%, allele B ${Math.round(b*100)}%"><span class="allele-track"><i style="width:${a*100}%"></i></span><span class="allele-track allele-b"><i style="width:${b*100}%"></i></span></div></div></div>`}).join('')}</section>`).join('')}`
122: }
123: function renderAbilities(c) {
